    activities.forEach((activity, activityIndex) => { const validation = validateActivityExport(activity); totals.push(validation.total); (activity.budgetLines || []).forEach((line, lineIndex) => { const budget = lineSufficiency(line), total = validation.lineTotals[lineIndex]; recapRows.push([activityIndex + 1, activity.activityName || '-', activity.activityDate || '-', activity.status === 'confirmed' ? 'Confirmed' : 'Draft', (activity.directorates || []).map(code => catalogs()[code] || code).join(', ') || '-', line.accountCode || '-', line.templateName || line.accountName || '-', total, Number(budget.available) || 0, (Number(budget.available) || 0) - total]); }); const detail = buildActivityDetailSheet(activity, usedNames); XLSX.utils.book_append_sheet(workbook, detail.worksheet, detail.name); });
